import styled from 'styled-components';


export const Blocks = styled.div`
  display: flex;
  justify-content: space-evenly;
  padding: 100px;
  border:1px solid black;
`;

export const Button = styled.button`
width:clamp(100px, 11vw, 200px);
`

export const Btn = styled.button`
width:clamp(50px, 6vw, 100px);
`

export const btnmain = () => {
  const handleClick1 = () => {
    console.log('Нажата кнопка Primery');
  };



  return (
    <Blocks className="buttons">
      <Button className="button1" onClick={handleClick1}>Primery</Button>
      <Button className="button2" >Secondary</Button>
      <Button className="button3" >Secondary2</Button>
      <Btn>заглушка</Btn>
    </Blocks>
  );
};
